endpoints.responseShape:
{
  "id": "<uuid>",
  "organizationId": "<uuid, copied from clinic.organizationId>",
  "clinicId": "<uuid>",
  "physicianId": "<uuid, PhysicianProfile.id — NOT userId>",
  "patientUserId": "<uuid|arbitrary string>",
  "subprofileId": "<uuid>|null",
  "clinicPatientId": "<uuid>|null",
  "status": "IN_PROGRESS",
  "audioUrl": null,
  "rawTranscript": null,
  "rawNotes": "<string>|null",
  "subjective": null,
  "objective": null,
  "assessment": null,
  "plan": null,
  "chiefComplaint": "<string>|null",
  "diagnosis": [],
  "diagnosisCodes": null,
  "followUpDate": null,
  "followUpNotes": null,
  "sharedSections": null,
  "patientFeedback": null,
  "patientFeedbackAt": null,
  "patientDismissedAt": null,
  "visitDate": "2026-09-03T10:11:12.345Z",
  "specialtyData": null,
  "completedAt": null,
  "createdAt": "2026-09-03T10:11:12.345Z",
  "updatedAt": "2026-09-03T10:11:12.345Z",
  "deletedAt": null,
  "clinic": { "name": "<string>" },
  "subprofile": null,
  "clinicPatient": null
}

// When subprofileId resolves non-null:
//   "subprofile": { "name": "<string>", "relation": "SELF|SPOUSE|CHILD|PARENT|SIBLING|OTHER" }
// When clinicPatientId is non-null:
//   "clinicPatient": { "id": "<uuid>", "name": "<string>", "phone": "<string>|null" }

// Key order = Prisma model field order (as listed above), then relations in include order:
// clinic, subprofile, clinicPatient.
// clinic has ONLY { name } — no id, no specialty (differs from GET / and GET /:id which return clinic.id).
// subprofile has ONLY { name, relation } — no id (differs from GET / and GET /:id which return subprofile.id).
// All DateTime values are JSON.stringify(Date) => ISO-8601 UTC with exactly 3 fractional digits and a 'Z'.
// `diagnosis` is String[] @default([]) => ALWAYS an array, never null; here always [].
// There is NO `appointmentId` key in the response — the Visit model has no such column.

// Identical shape for BOTH branches: the raw Visit row, all scalars, NO relations, NO `message`.
{
  "id": "<uuid>",
  "organizationId": "<uuid>",
  "clinicId": "<uuid>",
  "physicianId": "<uuid>",
  "patientUserId": "<string>",
  "subprofileId": "<uuid>|null",
  "clinicPatientId": "<uuid>|null",
  "status": "IN_PROGRESS|COMPLETED|CANCELLED|ARCHIVED",
  "audioUrl": "<string>|null",
  "rawTranscript": "<string>|null",
  "rawNotes": "<string>|null",
  "subjective": "<string>|null",
  "objective": "<string>|null",
  "assessment": "<string>|null",
  "plan": "<string>|null",
  "chiefComplaint": "<string>|null",
  "diagnosis": ["<string>"],
  "diagnosisCodes": null,
  "followUpDate": "2026-09-10T00:00:00.000Z"|null,
  "followUpNotes": "<string>|null",
  "sharedSections": null,
  "patientFeedback": "<string>|null",
  "patientFeedbackAt": "<iso>|null",
  "patientDismissedAt": "<iso>|null",
  "visitDate": "<iso>",
  "specialtyData": null,
  "completedAt": "<iso>|null",
  "createdAt": "<iso>",
  "updatedAt": "<iso>",
  "deletedAt": "<iso>|null"
}

// `diagnosis`: String[] @default([]) — ALWAYS an array, NEVER null; [] when empty.
// `diagnosisCodes`: Json? — null when never set, or the client-supplied array verbatim,
//    e.g. [{"code":"E11.9","description":"Type 2 diabetes mellitus without complications"}].
//    The client (VisitDetailPage autosave) sends [] routinely, so `[]` and `null` are BOTH real
//    values and are NOT interchangeable.
// `sharedSections`: Json? — null or e.g. ["subjective","assessment","plan"] (set only by /complete).
// `specialtyData`: Json? — null or an arbitrary flat object of string values, plus a `__templateKey` key
//    when it was populated by generate-soap, e.g. {"iop_od":"14","iop_os":"15","__templateKey":"ophthalmology"}.
// followUpDate is a full ISO instant even though the client sends 'YYYY-MM-DD'.
// No relation keys (clinic/physician/subprofile/clinicPatient) and no patientUser here.

{
  "message": "Visit archived successfully"
}

// Exactly one key. NOT the visit, NOT { success: true }, NOT 204 No Content.
// Note the sibling route DELETE /:id/investigations/:invId returns { "success": true } instead —
// the two delete-ish routes in this file are deliberately inconsistent.

{
  "id": "<uuid>",
  "patientFeedback": "<string>|null",
  "patientFeedbackAt": "2026-09-03T10:11:12.345Z"|null
}

// Exactly THREE keys, in this order (Prisma `select` order == schema field order here).
// The request field is named `note`; the response key is `patientFeedback` — the names differ.
// patientFeedbackAt is an ISO-8601 UTC instant with 3 fractional digits + 'Z', or null.
// Both keys are null together when the note is cleared.

{
  "patientFeedback": "<trimmed string>",
  "patientFeedbackAt": "2026-09-03T10:11:12.345Z"
}

// Exactly TWO keys — NO `id`, unlike PATCH /:id/patient-note which returns three.
// Neither value can be null on a 200 (the handler rejects empty text and always stamps the date).
// The request field is `feedback`; the response key is `patientFeedback` — names differ.
// patientFeedbackAt is an ISO-8601 UTC instant with exactly 3 fractional digits + 'Z'.
// Hand-built object literal, so key order is exactly as written above.

{
  "message": "Visit removed from your inbox"
}

// Exactly one key. Not 204, not { success: true }, and NOT the updated visit —
// the handler awaits prisma.visit.update but DISCARDS its result.
